import { text, integer, checkbox, json, timestamp } from '@keystone-6/core/fields';
import { domainList, name, money, currency, rel } from './domainFields';
export const TicketType = domainList('canManageTours', { name: name(), tour: rel('Tour.ticketTypes'), priceCents: money(), currencyCode: currency(), countsTowardCapacity: checkbox({ defaultValue: true }), seatsUsed: integer({ defaultValue: 1, validation: { min: 0 } }), minAge: integer(), maxAge: integer(), active: checkbox({ defaultValue: true }), pricingRules: rel('PricingRule.ticketType', true) });
export const AddOn = domainList('canManageTours', { name: name(), tour: rel('Tour.addOns'), priceCents: money(), currencyCode: currency(), perPerson: checkbox({ defaultValue: true }), inventory: integer({ validation: { min: 0 } }) });
export const MeetingPoint = domainList('canManageTours', { name: name(), address: text(), latitude: text(), longitude: text(), instructions: text(), mapLink: text(), tours: rel('Tour.meetingPoint', true) });
export const CancellationPolicy = domainList('canManageTours', { name: name(), rules: json({ defaultValue: [{ hoursBefore: 24, refundBps: 10000 }, { hoursBefore: 0, refundBps: 0 }] }), weatherFullRefund: checkbox({ defaultValue: true }), tours: rel('Tour.cancellationPolicy', true) });
export const PricingRule = domainList('canManageTours', { name: name(), tour: rel('Tour.pricingRules'), ticketType: rel('TicketType.pricingRules'), validFrom: timestamp(), validTo: timestamp(), weekdays: json(), adjustBps: integer(), overridePriceCents: integer({ validation: { min: 0 } }), currencyCode: currency() });
export const Schedule = domainList('canManageDepartures', { name: name(), tour: rel('Tour.schedules'), rrule: text({ defaultValue: 'FREQ=DAILY' }), startTimes: json({ defaultValue: ['09:00'] }), validFrom: timestamp(), validTo: timestamp(), capacityOverride: integer({ validation: { min: 1 } }), departures: rel('Departure.schedule', true) });
